/* mcc lex: makes a scanner in C from a description, in the manner of flex.
   The scanner is a table of a deterministic automaton and one loop over it;
   an input file is read whole. Not done: REJECT, yymore, trailing context
   where both parts vary in length, case-insensitive scanners. */
#include "mcc.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

