/* ---- regular expressions ---- */

enum { N_SET, N_CAT, N_ALT, N_STAR, N_PLUS, N_OPT, N_EMPTY, N_REP };

typedef struct Node {
    int kind, lo, hi;
    struct Node *a, *b;
    u8 set[32];
} Node;

typedef struct Def {
    char *name, *text;
} Def;

typedef struct Rule {
    Node *re;
    int bol, trail, eof, shared, line;
    u8 *sc; /* one flag for each start condition */
    char *action;
} Rule;

static Def *defs;
static int ndefs;
static char **sc_names;
static u8 *sc_excl;
static int nsc;
static Rule *rules;
static int nrules, caprules;
static const char *in_name;
static int in_line;
static int opt_noyywrap, opt_nounput, opt_noinput, opt_yylineno, opt_nodefault;
static const char *rp; /* where the expression parser stands */
static const char *rtop_end;
static int rnest;

static void lfail(const char *msg, const char *arg)
{
    fprintf(stderr, "%s:%d: ", in_name, in_line);
    fprintf(stderr, msg, arg);
    fprintf(stderr, "\n");
    exit(1);
}

static Node *node(int kind, Node *a, Node *b)
{
    Node *n = (Node *)xmalloc(sizeof(Node));
    memset(n, 0, sizeof *n);
    n->kind = kind;
    n->a = a;
    n->b = b;
    return n;
}

static Node *lit(int c)
{
    Node *n = node(N_SET, 0, 0);
    n->set[(c & 255) >> 3] |= (u8)(1 << (c & 7));
    return n;
}

static int escape(void)
{
    int c = (u8)*rp++, v = 0, k;
    switch (c) {
    case 'n': return '\n';
    case 't': return '\t';
    case 'r': return '\r';
    case 'f': return '\f';
    case 'v': return '\v';
    case 'a': return 7;
    case 'b': return '\b';
    case 'x':
        for (k = 0; k < 2; k++) {
            int d = (u8)*rp;
            if (d >= '0' && d <= '9')
                v = v * 16 + d - '0';
            else if ((d | 32) >= 'a' && (d | 32) <= 'f')
                v = v * 16 + (d | 32) - 'a' + 10;
            else
                break;
            rp++;
        }
        return v;
    }
    if (c >= '0' && c <= '7') {
        v = c - '0';
        for (k = 0; k < 2 && *rp >= '0' && *rp <= '7'; k++)
            v = v * 8 + *rp++ - '0';
        return v & 255;
    }
    if (!c)
        lfail("an expression ends in a backslash", 0);
    return c;
}

static int in_named(const char *name, size_t n, int c)
{
    static const char *const names[] = {"alpha", "digit", "alnum", "upper", "lower", "space", "blank", "punct", "xdigit", "print", "graph", "cntrl"};
    int k, up = c >= 'A' && c <= 'Z', lo = c >= 'a' && c <= 'z', dg = c >= '0' && c <= '9';
    for (k = 0; k < 12; k++)
        if (strlen(names[k]) == n && memcmp(names[k], name, n) == 0)
            break;
    switch (k) {
    case 0: return up || lo;
    case 1: return dg;
    case 2: return up || lo || dg;
    case 3: return up;
    case 4: return lo;
    case 5: return c == ' ' || (c >= 9 && c <= 13);
    case 6: return c == ' ' || c == '\t';
    case 7: return c > 32 && c < 127 && !(up || lo || dg);
    case 8: return dg || ((c | 32) >= 'a' && (c | 32) <= 'f');
    case 9: return c >= 32 && c < 127;
    case 10: return c > 32 && c < 127;
    case 11: return c < 32 || c == 127;
    }
    lfail("unknown character class name", 0);
    return 0;
}

static Node *char_class(void)
{
    Node *n = node(N_SET, 0, 0);
    int neg = 0, c, d, first = 1;
    if (*rp == '^') {
        neg = 1;
        rp++;
    }
    for (;; first = 0) {
        if (!*rp)
            lfail("unterminated character class", 0);
        if (*rp == ']' && !first) {
            rp++;
            break;
        }
        if (rp[0] == '[' && rp[1] == ':') {
            const char *e = strstr(rp + 2, ":]");
            if (!e)
                lfail("unterminated character class name", 0);
            for (c = 0; c < 256; c++)
                if (in_named(rp + 2, (size_t)(e - rp - 2), c))
                    n->set[c >> 3] |= (u8)(1 << (c & 7));
            rp = e + 2;
            continue;
        }
        c = (u8)*rp++;
        if (c == '\\')
            c = escape();
        d = c;
        if (rp[0] == '-' && rp[1] && rp[1] != ']') {
            rp++;
            d = (u8)*rp++;
            if (d == '\\')
                d = escape();
        }
        for (; c <= d; c++)
            n->set[c >> 3] |= (u8)(1 << (c & 7));
    }
    if (neg)
        for (c = 0; c < 32; c++)
            n->set[c] = (u8)~n->set[c];
    return n;
}

static Node *parse_alt(void);

static Node *parse_atom(void)
{
    Node *n = 0;
    int c = (u8)*rp++;
    switch (c) {
    case '(':
        rnest++;
        n = parse_alt();
        rnest--;
        if (*rp != ')')
            lfail("missing ) in an expression", 0);
        rp++;
        return n;
    case '"':
        n = node(N_EMPTY, 0, 0);
        while (*rp != '"') {
            if (!*rp)
                lfail("unterminated string in an expression", 0);
            c = (u8)*rp++;
            if (c == '\\')
                c = escape();
            n = node(N_CAT, n, lit(c));
        }
        rp++;
        return n;
    case '[':
        return char_class();
    case '.':
        n = node(N_SET, 0, 0);
        memset(n->set, 255, 32);
        n->set['\n' >> 3] &= (u8)~(1 << ('\n' & 7));
        return n;
    case '\\':
        return lit(escape());
    case '{': {
        const char *e = strchr(rp, '}'), *save_rp, *save_end;
        int k;
        if (!e)
            lfail("missing } in an expression", 0);
        for (k = 0; k < ndefs; k++)
            if (strlen(defs[k].name) == (size_t)(e - rp) && memcmp(defs[k].name, rp, (size_t)(e - rp)) == 0)
                break;
        if (k == ndefs)
            lfail("undefined name in an expression: %s", rp);
        save_rp = e + 1;
        save_end = rtop_end;
        rp = defs[k].text;
        rnest++;
        n = parse_alt();
        rnest--;
        if (*rp)
            lfail("bad definition of %s", defs[k].name);
        rp = save_rp;
        rtop_end = save_end;
        return n;
    }
    }
    return lit(c);
}

static Node *parse_post(void)
{
    Node *n = parse_atom();
    for (;;) {
        if (*rp == '*')
            n = node(N_STAR, n, 0), rp++;
        else if (*rp == '+')
            n = node(N_PLUS, n, 0), rp++;
        else if (*rp == '?')
            n = node(N_OPT, n, 0), rp++;
        else if (*rp == '{' && rp[1] >= '0' && rp[1] <= '9') {
            int lo = 0, hi;
            rp++;
            while (*rp >= '0' && *rp <= '9')
                lo = lo * 10 + *rp++ - '0';
            hi = lo;
            if (*rp == ',') {
                rp++;
                hi = -1;
                if (*rp >= '0' && *rp <= '9') {
                    hi = 0;
                    while (*rp >= '0' && *rp <= '9')
                        hi = hi * 10 + *rp++ - '0';
                }
            }
            if (*rp != '}')
                lfail("bad repeat count", 0);
            rp++;
            n = node(N_REP, n, 0);
            n->lo = lo;
            n->hi = hi;
        } else
            break;
    }
    return n;
}

static Node *parse_cat(void)
{
    Node *n = node(N_EMPTY, 0, 0);
    while (*rp && *rp != '|' && *rp != ')') {
        if (!rnest && (*rp == '/' || (*rp == '$' && rp + 1 == rtop_end)))
            break;
        n = node(N_CAT, n, parse_post());
    }
    return n;
}

static Node *parse_alt(void)
{
    Node *n = parse_cat();
    while (*rp == '|') {
        rp++;
        n = node(N_ALT, n, parse_cat());
    }
    return n;
}

/* The length of everything the expression matches, or -1 if it varies. */
static int fixed_len(Node *n)
{
    int a, b;
    switch (n->kind) {
    case N_SET: return 1;
    case N_EMPTY: return 0;
    case N_CAT:
        a = fixed_len(n->a);
        b = fixed_len(n->b);
        return a < 0 || b < 0 ? -1 : a + b;
    case N_ALT:
        a = fixed_len(n->a);
        b = fixed_len(n->b);
        return a == b ? a : -1;
    case N_REP:
        a = fixed_len(n->a);
        return a >= 0 && n->lo == n->hi ? a * n->lo : -1;
    }
    return -1;
}

/* ---- the automata ---- */

typedef struct NState {
    int e1, e2;   /* moves on nothing */
    Node *on;     /* a move on a character of this set ... */
    int to;       /* ... leads here */
    int accept;   /* rule + 1 */
} NState;

static NState *nfa;
static int nnfa, capnfa;

static int nstate(void)
{
    if (nnfa == capnfa) {
        capnfa = capnfa ? 2 * capnfa : 1024;
        nfa = (NState *)xrealloc(nfa, (size_t)capnfa * sizeof(NState));
    }
    nfa[nnfa].e1 = nfa[nnfa].e2 = nfa[nnfa].to = -1;
    nfa[nnfa].on = 0;
    nfa[nnfa].accept = 0;
    return nnfa++;
}

static void eps(int from, int to)
{
    if (nfa[from].e1 < 0)
        nfa[from].e1 = to;
    else if (nfa[from].e2 < 0)
        nfa[from].e2 = to;
    else {
        int mid = nstate();
        nfa[mid].e1 = nfa[from].e2;
        nfa[mid].e2 = to;
        nfa[from].e2 = mid;
    }
}

static void build(Node *n, int *start, int *end)
{
    int s = nstate(), e = nstate(), s1, e1, s2, e2, k;
    *start = s;
    *end = e;
    switch (n->kind) {
    case N_SET:
        nfa[s].on = n;
        nfa[s].to = e;
        break;
    case N_EMPTY:
        eps(s, e);
        break;
    case N_CAT:
        build(n->a, &s1, &e1);
        build(n->b, &s2, &e2);
        eps(s, s1);
        eps(e1, s2);
        eps(e2, e);
        break;
    case N_ALT:
        build(n->a, &s1, &e1);
        build(n->b, &s2, &e2);
        eps(s, s1);
        eps(s, s2);
        eps(e1, e);
        eps(e2, e);
        break;
    case N_STAR:
    case N_PLUS:
    case N_OPT:
        build(n->a, &s1, &e1);
        eps(s, s1);
        eps(e1, e);
        if (n->kind != N_PLUS)
            eps(s, e);
        if (n->kind != N_OPT)
            eps(e1, s1);
        break;
    case N_REP: {
        int at = s;
        for (k = 0; k < n->lo; k++) {
            build(n->a, &s1, &e1);
            eps(at, s1);
            at = e1;
        }
        if (n->hi < 0) {
            build(n->a, &s1, &e1);
            eps(at, s1);
            eps(e1, s1);
            eps(at, e);
            eps(e1, e);
        } else {
            for (; k < n->hi; k++) {
                build(n->a, &s1, &e1);
                eps(at, s1);
                eps(at, e);
                at = e1;
            }
            eps(at, e);
        }
        break;
    }
    }
}

static u8 ec[256];
static int nec;
static int rep[256]; /* a character of each class */

static void split_classes(Node *n)
{
    int map[512], c, k;
    if (!n)
        return;
    if (n->kind != N_SET) {
        split_classes(n->a);
        split_classes(n->b);
        return;
    }
    for (k = 0; k < 512; k++)
        map[k] = -1;
    k = 0;
    for (c = 0; c < 256; c++) {
        int key = ec[c] * 2 + ((n->set[c >> 3] >> (c & 7)) & 1);
        if (map[key] < 0)
            map[key] = k++;
        ec[c] = (u8)map[key];
    }
    nec = k;
}

static u32 **dsets;   /* each deterministic state: the set of states of the other automaton it stands for */
static int ndfa, capdfa, nwords;
static short *dnext;  /* ndfa * nec */
static int *dhash;
static int ndhash;

static void closure(u32 *set)
{
    int *stack = (int *)xmalloc((size_t)nnfa * sizeof(int)), top = 0, k;
    for (k = 0; k < nnfa; k++)
        if (set[k >> 5] >> (k & 31) & 1)
            stack[top++] = k;
    while (top) {
        int s = stack[--top], j;
        for (j = 0; j < 2; j++) {
            int t = j ? nfa[s].e2 : nfa[s].e1;
            if (t >= 0 && !(set[t >> 5] >> (t & 31) & 1)) {
                set[t >> 5] |= 1U << (t & 31);
                stack[top++] = t;
            }
        }
    }
    free(stack);
}

static int dstate(u32 *set)
{
    u32 h = 2166136261U;
    int k, slot;
    for (k = 0; k < nwords; k++)
        h = (h ^ set[k]) * 16777619U;
    if (2 * (ndfa + 1) > ndhash) {
        int n = ndhash ? 2 * ndhash : 1024, j;
        free(dhash);
        dhash = (int *)xmalloc((size_t)n * sizeof(int));
        for (j = 0; j < n; j++)
            dhash[j] = -1;
        ndhash = n;
        for (j = 0; j < ndfa; j++) {
            u32 hh = 2166136261U;
            for (k = 0; k < nwords; k++)
                hh = (hh ^ dsets[j][k]) * 16777619U;
            for (slot = (int)(hh % (u32)n); dhash[slot] >= 0; slot = (slot + 1) % n)
                ;
            dhash[slot] = j;
        }
    }
    for (slot = (int)(h % (u32)ndhash); dhash[slot] >= 0; slot = (slot + 1) % ndhash)
        if (memcmp(dsets[dhash[slot]], set, (size_t)nwords * 4) == 0)
            return dhash[slot];
    if (ndfa == capdfa) {
        capdfa = capdfa ? 2 * capdfa : 256;
        dsets = (u32 **)xrealloc(dsets, (size_t)capdfa * sizeof(u32 *));
    }
    dsets[ndfa] = (u32 *)xmalloc((size_t)nwords * 4);
    memcpy(dsets[ndfa], set, (size_t)nwords * 4);
    dhash[slot] = ndfa;
    return ndfa++;
}

/* ---- reading the description ---- */

static char *text_dup(const char *s, size_t n)
{
    char *p = (char *)xmalloc(n + 1);
    memcpy(p, s, n);
    p[n] = 0;
    return p;
}

static int sc_find(const char *name, size_t n)
{
    int k;
    for (k = 0; k < nsc; k++)
        if (strlen(sc_names[k]) == n && memcmp(sc_names[k], name, n) == 0)
            return k;
    return -1;
}

static void sc_add(const char *name, size_t n, int excl)
{
    sc_names = (char **)xrealloc(sc_names, (size_t)(nsc + 1) * sizeof(char *));
    sc_excl = (u8 *)xrealloc(sc_excl, (size_t)nsc + 1);
    sc_names[nsc] = text_dup(name, n);
    sc_excl[nsc++] = (u8)excl;
}

/* Where the expression at s ends: at the first blank outside quotes, classes and braces. */
static const char *pattern_end(const char *s)
{
    for (; *s && *s != ' ' && *s != '\t' && *s != '\n'; s++) {
        if (*s == '\\' && s[1])
            s++;
        else if (*s == '"') {
            for (s++; *s && *s != '"' && *s != '\n'; s++)
                if (*s == '\\' && s[1])
                    s++;
            if (*s != '"')
                lfail("unterminated string in an expression", 0);
        } else if (*s == '[') {
            s++;
            if (*s == '^')
                s++;
            if (*s == ']')
                s++;
            for (; *s && *s != ']' && *s != '\n'; s++) {
                if (*s == '\\' && s[1])
                    s++;
                else if (s[0] == '[' && s[1] == ':') {
                    const char *e = strstr(s + 2, ":]");
                    if (e)
                        s = e + 1;
                }
            }
            if (*s != ']')
                lfail("unterminated character class", 0);
        }
    }
    return s;
}

/* The C code from s to the brace that closes the first one; *end is left just past it. */
static const char *skip_braces(const char *s)
{
    int depth = 0;
    for (; *s; s++) {
        if (*s == '\n')
            in_line++;
        if (*s == '"' || *s == '\'') {
            int q = *s;
            for (s++; *s && *s != q; s++)
                if (*s == '\\' && s[1])
                    s++;
            if (!*s)
                break;
        } else if (s[0] == '/' && s[1] == '*') {
            const char *e = strstr(s + 2, "*/");
            if (!e)
                break;
            for (; s < e + 1; s++)
                if (*s == '\n')
                    in_line++;
        } else if (s[0] == '/' && s[1] == '/') {
            while (s[1] && s[1] != '\n')
                s++;
        } else if (*s == '{') {
            depth++;
        } else if (*s == '}' && --depth == 0) {
            return s + 1;
        }
    }
    lfail("unterminated action", 0);
    return s;
}

static const char *line_end(const char *s)
{
    while (*s && *s != '\n')
        s++;
    return s;
}

static Buf out;

static void o(const char *s) { buf_put(&out, s, strlen(s)); }

static void onum(long v)
{
    char num[24];
    sprintf(num, "%ld", v);
    o(num);
}

static void olines(const char *const *lines)
{
    for (; *lines; lines++) {
        o(*lines);
        o("\n");
    }
}

static void add_rule(Rule *r)
{
    if (nrules == caprules) {
        caprules = caprules ? 2 * caprules : 64;
        rules = (Rule *)xrealloc(rules, (size_t)caprules * sizeof(Rule));
    }
    rules[nrules++] = *r;
}

int lex_main(int argc, char **argv)
{
    const char *out_name = "lex.yy.c", *p, *e;
    char *src;
    size_t len;
    Buf top, prologue, user;
    int k, c, started = 0;
    u8 *scope[16];
    int nscope = 0;
    for (k = 0; k < argc; k++) {
        if (strncmp(argv[k], "-o", 2) == 0)
            out_name = argv[k][2] ? argv[k] + 2 : argv[++k];
        else if (strncmp(argv[k], "--outfile=", 10) == 0)
            out_name = argv[k] + 10;
        else if (strcmp(argv[k], "--version") == 0 || strcmp(argv[k], "-V") == 0) {
            puts("flex 2.6.4 (mcc lex)");
            return 0;
        } else if (argv[k][0] != '-')
            in_name = argv[k];
    }
    if (!in_name || !out_name)
        die("usage: mcc lex [-o out.c] file.l");
    src = (char *)os_read_file(in_name, &len);
    if (!src)
        die("cannot read %s", in_name);
    src = text_dup(src, len);
    memset(&top, 0, sizeof top);
    memset(&prologue, 0, sizeof prologue);
    memset(&user, 0, sizeof user);
    sc_add("INITIAL", 7, 0);
    in_line = 1;

    /* the definitions */
    for (p = src; *p; p = *e ? e + 1 : e, in_line++) {
        e = line_end(p);
        if (p[0] == '%' && p[1] == '%')
            break;
        if (p[0] == '%' && p[1] == '{') {
            const char *q = strstr(p, "\n%}");
            if (!q)
                lfail("unterminated %%{", 0);
            buf_put(&top, p + 2, (size_t)(q + 1 - p - 2));
            for (; p < q + 1; p++)
                if (*p == '\n')
                    in_line++;
            e = line_end(q + 1);
            continue;
        }
        if (p[0] == '%') {
            const char *w = p + 1, *q;
            int excl = p[1] == 'x';
            while (w < e && *w != ' ' && *w != '\t')
                w++;
            if ((p[1] == 'x' || p[1] == 's') && w == p + 2) {
                for (;;) {
                    while (w < e && (*w == ' ' || *w == '\t'))
                        w++;
                    q = w;
                    while (w < e && *w != ' ' && *w != '\t')
                        w++;
                    if (w == q)
                        break;
                    sc_add(q, (size_t)(w - q), excl);
                }
            } else if (strncmp(p, "%option", 7) == 0) {
                char *l = text_dup(p, (size_t)(e - p));
                opt_noyywrap |= strstr(l, "noyywrap") != 0;
                opt_nounput |= strstr(l, "nounput") != 0;
                opt_noinput |= strstr(l, "noinput") != 0;
                opt_yylineno |= strstr(l, "yylineno") != 0;
                opt_nodefault |= strstr(l, "nodefault") != 0;
                free(l);
            }
            continue;
        }
        if (p[0] == ' ' || p[0] == '\t') {
            buf_put(&top, p, (size_t)(e - p));
            buf_u8(&top, '\n');
            continue;
        }
        if (p[0] == '/' && p[1] == '*') {
            const char *q = strstr(p, "*/");
            if (!q)
                lfail("unterminated comment", 0);
            for (; p < q; p++)
                if (*p == '\n')
                    in_line++;
            e = line_end(q);
            continue;
        }
        if (e > p) {
            const char *w = p, *t = e;
            while (w < e && *w != ' ' && *w != '\t')
                w++;
            defs = (Def *)xrealloc(defs, (size_t)(ndefs + 1) * sizeof(Def));
            defs[ndefs].name = text_dup(p, (size_t)(w - p));
            while (w < e && (*w == ' ' || *w == '\t'))
                w++;
            while (t > w && (t[-1] == ' ' || t[-1] == '\t' || t[-1] == '\r'))
                t--;
            defs[ndefs++].text = text_dup(w, (size_t)(t - w));
        }
    }
    if (!*p)
        lfail("no rules section", 0);
    p = line_end(p);
    p = *p ? p + 1 : p;
    in_line++;

    /* the rules */
    while (*p) {
        Rule r;
        const char *q;
        e = line_end(p);
        if (p[0] == '%' && p[1] == '%') {
            p = *e ? e + 1 : e;
            buf_put(&user, p, strlen(p));
            break;
        }
        if (p[0] == '%' && p[1] == '{') {
            q = strstr(p, "\n%}");
            if (!q)
                lfail("unterminated %%{", 0);
            buf_put(&prologue, p + 2, (size_t)(q + 1 - p - 2));
            for (; p < q + 1; p++)
                if (*p == '\n')
                    in_line++;
            p = line_end(q + 1);
            p = *p ? p + 1 : p;
            in_line++;
            continue;
        }
        q = p;
        while (*q == ' ' || *q == '\t')
            q++;
        if (q == e) {
            p = *e ? e + 1 : e;
            in_line++;
            continue;
        }
        if (q > p && !nscope) {
            /* indented and outside any scope: code for the top of the scanner, or a comment */
            if (!started) {
                buf_put(&prologue, p, (size_t)(e - p));
                buf_u8(&prologue, '\n');
            }
            p = *e ? e + 1 : e;
            in_line++;
            continue;
        }
        if (nscope && *q == '}') {
            nscope--;
            p = *e ? e + 1 : e;
            in_line++;
            continue;
        }
        started = 1;
        memset(&r, 0, sizeof r);
        r.line = in_line;
        r.sc = (u8 *)xmalloc((size_t)nsc);
        memset(r.sc, 0, (size_t)nsc);
        if (*q == '<' && q[1] != '<') {
            const char *close = strchr(q, '>');
            if (!close || close > e)
                lfail("bad start condition list", 0);
            for (q++; q < close;) {
                const char *w = q;
                while (w < close && *w != ',')
                    w++;
                if (w == q + 1 && *q == '*')
                    memset(r.sc, 1, (size_t)nsc);
                else {
                    c = sc_find(q, (size_t)(w - q));
                    if (c < 0)
                        lfail("undeclared start condition", 0);
                    r.sc[c] = 1;
                }
                q = w < close ? w + 1 : w;
            }
            q = close + 1;
            if (*q == '{') {
                const char *w = q + 1;
                while (w < e && (*w == ' ' || *w == '\t'))
                    w++;
                if (w == e) {
                    if (nscope == 16)
                        lfail("start condition scopes nested too deeply", 0);
                    scope[nscope++] = r.sc;
                    p = *e ? e + 1 : e;
                    in_line++;
                    continue;
                }
            }
        } else if (nscope) {
            memcpy(r.sc, scope[nscope - 1], (size_t)nsc);
        } else {
            for (c = 0; c < nsc; c++)
                r.sc[c] = !sc_excl[c];
            r.eof = 2; /* provisionally: an end-of-file rule here is for the conditions that have none */
        }
        if (strncmp(q, "<<EOF>>", 7) == 0) {
            r.eof = r.eof == 2 ? 2 : 1;
            q += 7;
        } else {
            const char *pe = pattern_end(q);
            char *pat;
            Node *head;
            r.eof = 0;
            if (*q == '^') {
                r.bol = 1;
                q++;
            }
            pat = text_dup(q, (size_t)(pe - q));
            rp = pat;
            rtop_end = pat + strlen(pat);
            rnest = 0;
            head = parse_alt();
            if (*rp == '/') {
                Node *tail;
                int tl, hl;
                rp++;
                tail = parse_alt();
                tl = fixed_len(tail);
                hl = fixed_len(head);
                if (tl >= 0)
                    r.trail = tl;
                else if (hl >= 0)
                    r.trail = -hl - 1;
                else
                    lfail("trailing context where neither part has a fixed length is not supported", 0);
                head = node(N_CAT, head, tail);
            } else if (*rp == '$') {
                rp++;
                head = node(N_CAT, head, lit('\n'));
                r.trail = 1;
            }
            if (*rp)
                lfail("bad expression near: %s", rp);
            r.re = head;
            q = pe;
        }
        while (*q == ' ' || *q == '\t')
            q++;
        if (*q == '{') {
            const char *end = skip_braces(q), *le = line_end(end);
            r.action = text_dup(q, (size_t)(le - q));
            e = le;
        } else if (*q == '|' && (q[1] == '\n' || q[1] == 0 || q[1] == ' ' || q[1] == '\t')) {
            r.shared = 1;
            r.action = text_dup("", 0);
        } else {
            r.action = text_dup(q, (size_t)(e - q));
        }
        add_rule(&r);
        p = *e ? e + 1 : e;
        in_line++;
    }

    /* the automaton: one start for each start condition, at the start of a line and elsewhere */
    {
        int *starts = (int *)xmalloc((size_t)nrules * sizeof(int)), *begin = (int *)xmalloc((size_t)nsc * 2 * sizeof(int));
        short *accept;
        u32 *set, *nset;
        int s, e2, d, done;
        for (k = 0; k < 256; k++)
            ec[k] = 0;
        nec = 1;
        for (k = 0; k < nrules; k++)
            split_classes(rules[k].re);
        for (c = 255; c >= 0; c--)
            rep[ec[c]] = c;
        for (k = 0; k < nrules; k++) {
            starts[k] = -1;
            if (!rules[k].re)
                continue;
            build(rules[k].re, &s, &e2);
            nfa[e2].accept = k + 1;
            starts[k] = s;
        }
        for (c = 0; c < nsc * 2; c++) {
            begin[c] = nstate();
            for (k = 0; k < nrules; k++)
                if (starts[k] >= 0 && rules[k].sc[c / 2] && (!rules[k].bol || (c & 1)))
                    eps(begin[c], starts[k]);
        }
        nwords = (nnfa + 31) / 32;
        set = (u32 *)xmalloc((size_t)nwords * 4);
        nset = (u32 *)xmalloc((size_t)nwords * 4);
        memset(set, 0, (size_t)nwords * 4);
        dstate(set); /* state 0 stands for nothing at all */
        for (c = 0; c < nsc * 2; c++) {
            memset(set, 0, (size_t)nwords * 4);
            set[begin[c] >> 5] |= 1U << (begin[c] & 31);
            closure(set);
            begin[c] = dstate(set);
        }
        for (done = 0; done < ndfa; done++) {
            dnext = (short *)xrealloc(dnext, (size_t)(done + 1) * (size_t)nec * sizeof(short));
            for (d = 0; d < nec; d++) {
                int any = 0, ch = rep[d];
                memset(nset, 0, (size_t)nwords * 4);
                for (k = 0; k < nnfa; k++)
                    if ((dsets[done][k >> 5] >> (k & 31) & 1) && nfa[k].on && (nfa[k].on->set[ch >> 3] >> (ch & 7) & 1)) {
                        nset[nfa[k].to >> 5] |= 1U << (nfa[k].to & 31);
                        any = 1;
                    }
                if (!any) {
                    dnext[done * nec + d] = -1;
                    continue;
                }
                closure(nset);
                dnext[done * nec + d] = (short)dstate(nset);
                if (ndfa > 32000)
                    lfail("the scanner has too many states", 0);
            }
        }
        accept = (short *)xmalloc((size_t)ndfa * sizeof(short));
        for (d = 0; d < ndfa; d++) {
            accept[d] = 0;
            for (k = 0; k < nnfa; k++)
                if ((dsets[d][k >> 5] >> (k & 31) & 1) && nfa[k].accept && (!accept[d] || nfa[k].accept < accept[d]))
                    accept[d] = (short)nfa[k].accept;
        }

        /* the scanner */
        olines(skel_HEAD);
        if (opt_noyywrap)
            o("#define yywrap() 1\n");
        else
            o("extern int yywrap(void);\n");
        o("#define YY_USE_LINENO ");
        onum(opt_yylineno);
        o("\n#define YY_NODEFAULT ");
        onum(opt_nodefault);
        o("\n");
        for (k = 1; k < nsc; k++) {
            o("#define ");
            o(sc_names[k]);
            o(" ");
            onum(k);
            o("\n");
        }
        buf_put(&out, top.p, top.len);
        o("\nstatic const unsigned char yy_ec[256] = {");
        for (k = 0; k < 256; k++) {
            o(k % 24 ? " " : "\n    ");
            onum(ec[k]);
            o(",");
        }
        o("\n};\nstatic const short yy_next[");
        onum(ndfa);
        o("][");
        onum(nec);
        o("] = {\n");
        for (d = 0; d < ndfa; d++) {
            o("    {");
            for (k = 0; k < nec; k++) {
                onum(dnext[d * nec + k]);
                o(k + 1 < nec ? "," : "");
            }
            o("},\n");
        }
        o("};\nstatic const short yy_accept[] = {");
        for (d = 0; d < ndfa; d++) {
            o(d % 20 ? " " : "\n    ");
            onum(accept[d]);
            o(",");
        }
        o("\n};\nstatic const short yy_trail[] = {\n    0,");
        for (k = 0; k < nrules; k++) {
            o((k + 1) % 20 ? " " : "\n    ");
            onum(rules[k].trail);
            o(",");
        }
        o("\n};\nstatic const short yy_begin[] = {");
        for (c = 0; c < nsc * 2; c++) {
            o(" ");
            onum(begin[c]);
            o(",");
        }
        o("\n};\n");
        olines(skel_MID);
        if (!opt_nounput)
            olines(skel_UNPUT);
        if (!opt_noinput)
            olines(skel_INPUT);
        olines(skel_LEX);
        buf_put(&out, prologue.p, prologue.len);
        olines(skel_LOOP);
        /* end of file: a rule that names its conditions wins over one that does not */
        for (c = 0; c < nsc; c++) {
            int pick = -1;
            for (k = 0; k < nrules && pick < 0; k++)
                if (rules[k].eof == 1 && rules[k].sc[c])
                    pick = k;
            for (k = 0; k < nrules && pick < 0; k++)
                if (rules[k].eof == 2)
                    pick = k;
            if (pick < 0)
                continue;
            o("            case ");
            onum(c);
            o(":\n");
            o(rules[pick].action);
            o("\n                break;\n");
        }
        olines(skel_EOFEND);
        for (k = 0; k < nrules; k++) {
            if (rules[k].eof)
                continue;
            o("        case ");
            onum(k + 1);
            o(":\n");
            if (rules[k].shared)
                continue;
            o(rules[k].action);
            o("\n            YY_BREAK\n");
        }
        olines(skel_TAIL);
        buf_put(&out, user.p, user.len);
    }
    os_write_file(out_name, out.p, out.len, 0);
    return 0;
}
